`timescale 1ns/1ps

//=============================================================================
// apb_i2s.v
//-----------------------------------------------------------------------------
// Simplified I2S transceiver (APB slot 3): 32-bit frames, MSB first, master
// mode only.  SCK is generated by dividing clk_i (half-period = DIV+1
// cycles); TX data changes on the internal SCK falling edge and RX data is
// sampled on the rising edge; WS toggles once per 32-bit frame.  A LOOPBACK
// control bit routes sd_o back into the receiver for self-tests.
//
// APB register map (offsets within the 4 kB window):
//   0x00 CTRL       RW  bit0 EN, bit1 TX_EN, bit2 RX_EN, bit3 LOOPBACK,
//                       bit4 TX_IRQ_EN, bit5 RX_IRQ_EN
//   0x04 DIV        RW  [15:0] SCK half-period in clk_i cycles (>=1)
//   0x08 TXDATA     W   push a 32-bit sample into the TX FIFO (4 deep)
//   0x0C RXDATA     R   pop a received sample from the RX FIFO (4 deep)
//   0x10 STATUS     RO  bit0 BUSY(=EN), bit1 TX_EMPTY, bit2 TX_FULL,
//                       bit3 RX_EMPTY, bit4 RX_FULL
//   0x14 IRQ_STATUS W1C bit0 TX_DONE (TX FIFO drained & idle),
//                       bit1 RX_AVAIL (RX sample pushed)
//
// irq_o      = (TX_DONE & TX_IRQ_EN) | (RX_AVAIL & RX_IRQ_EN)
// tx_req_o   = !TX_FULL  (DMA request line: room for another sample)
// rx_req_o   = !RX_EMPTY (DMA request line: sample available)
//
// Plain Verilog (IEEE 1364-2001).
//=============================================================================

module apb_i2s (
  input  wire         clk_i,
  input  wire         rst_ni,

  // ---- I2S pins ----
  output wire         sck_o,
  output wire         ws_o,
  output wire         sd_o,
  input  wire         sd_i,

  output wire         irq_o,
  output wire         tx_req_o,
  output wire         rx_req_o,

  // ---- APB slave (slot 3) ----
  input  wire         psel_i,
  input  wire         penable_i,
  input  wire         pwrite_i,
  input  wire [11:0]  paddr_i,
  input  wire [31:0]  pwdata_i,
  output reg  [31:0]  prdata_o,
  output wire         pready_o,
  output wire         pslverr_o
);

  // -------------------------------------------------------------------------
  // Control registers
  // -------------------------------------------------------------------------
  reg        en_q, tx_en_q, rx_en_q, loop_q, tx_irq_en_q, rx_irq_en_q;
  reg [15:0] div_q;
  reg        tx_done_q, rx_avail_q;

  wire wr_c = psel_i && penable_i && pwrite_i;

  // -------------------------------------------------------------------------
  // FIFOs (4 x 32 each)
  // -------------------------------------------------------------------------
  reg [31:0] tx_fifo [0:3];
  reg [31:0] rx_fifo [0:3];
  reg [1:0]  tx_wr_ptr_q, tx_rd_ptr_q, rx_wr_ptr_q, rx_rd_ptr_q;
  reg [2:0]  tx_cnt_q, rx_cnt_q;

  wire tx_empty = (tx_cnt_q == 3'd0);
  wire tx_full  = (tx_cnt_q == 3'd4);
  wire rx_empty = (rx_cnt_q == 3'd0);
  wire rx_full  = (rx_cnt_q == 3'd4);

  wire apb_tx_push = wr_c && (paddr_i[7:2] == 6'h02) && !tx_full;  // 0x08
  wire apb_rx_pop  = psel_i && penable_i && !pwrite_i &&
                     (paddr_i[7:2] == 6'h03) && !rx_empty;         // 0x0C

  // -------------------------------------------------------------------------
  // Tick / SCK generation
  // -------------------------------------------------------------------------
  reg [15:0] div_cnt_q;
  reg        sck_q;
  reg        ws_q;
  reg [4:0]  bit_cnt_q;      // 0..31 within a frame

  wire tick = en_q && (div_cnt_q == div_q);

  reg [31:0] tx_shift_q;
  reg [31:0] rx_shift_q;
  reg        sd_o_q;

  wire sd_in = loop_q ? sd_o_q : sd_i;

  // engine FIFO handshakes (frame boundaries)
  reg        eng_tx_pop;     // pop TX FIFO at frame start
  reg        eng_rx_push;    // push RX FIFO at frame end
  reg [31:0] eng_rx_data;

  always @(posedge clk_i) begin
    if (!rst_ni) begin
      en_q <= 1'b0; tx_en_q <= 1'b0; rx_en_q <= 1'b0;
      loop_q <= 1'b0; tx_irq_en_q <= 1'b0; rx_irq_en_q <= 1'b0;
      div_q <= 16'd1;
      tx_done_q <= 1'b0; rx_avail_q <= 1'b0;
      div_cnt_q <= 16'd0; sck_q <= 1'b0; ws_q <= 1'b0; bit_cnt_q <= 5'd0;
      tx_shift_q <= 32'h0; rx_shift_q <= 32'h0; sd_o_q <= 1'b0;
      tx_wr_ptr_q <= 2'd0; tx_rd_ptr_q <= 2'd0;
      rx_wr_ptr_q <= 2'd0; rx_rd_ptr_q <= 2'd0;
      tx_cnt_q <= 3'd0; rx_cnt_q <= 3'd0;
      eng_tx_pop <= 1'b0; eng_rx_push <= 1'b0; eng_rx_data <= 32'h0;
    end else begin
      // ---- register writes ----
      if (wr_c) begin
        case (paddr_i[7:2])
          6'h00: begin                       // CTRL
            en_q        <= pwdata_i[0];
            tx_en_q     <= pwdata_i[1];
            rx_en_q     <= pwdata_i[2];
            loop_q      <= pwdata_i[3];
            tx_irq_en_q <= pwdata_i[4];
            rx_irq_en_q <= pwdata_i[5];
          end
          6'h01: div_q <= pwdata_i[15:0];    // DIV
          6'h05: begin                       // IRQ_STATUS W1C
            if (pwdata_i[0]) tx_done_q  <= 1'b0;
            if (pwdata_i[1]) rx_avail_q <= 1'b0;
          end
          default: ;
        endcase
      end

      // ---- default: engine FIFO strobes are single-cycle ----
      eng_tx_pop  <= 1'b0;
      eng_rx_push <= 1'b0;

      // ---- tick generator ----
      if (!en_q) begin
        div_cnt_q <= 16'd0;
      end else if (tick) begin
        div_cnt_q <= 16'd0;
        sck_q     <= ~sck_q;

        if (sck_q) begin
          // falling edge: drive the next TX bit, advance the frame
          if (tx_en_q) sd_o_q <= tx_shift_q[31];
          tx_shift_q <= {tx_shift_q[30:0], 1'b0};

          if (bit_cnt_q == 5'd31) begin
            bit_cnt_q <= 5'd0;
            ws_q      <= ~ws_q;
            if (tx_en_q) begin
              if (!tx_empty) begin
                eng_tx_pop <= 1'b1;
              end
            end
            if (rx_en_q) begin
              eng_rx_push <= 1'b1;
              eng_rx_data <= rx_shift_q;
              if (!rx_full) rx_avail_q <= 1'b1;
            end
          end else begin
            bit_cnt_q <= bit_cnt_q + 5'd1;
          end
        end else begin
          // rising edge: sample RX
          if (rx_en_q) rx_shift_q <= {rx_shift_q[30:0], sd_in};
        end
      end else begin
        div_cnt_q <= div_cnt_q + 16'd1;
      end

      // ---- TX FIFO: engine pop feeds the serializer ----
      if (eng_tx_pop) begin
        tx_shift_q <= tx_fifo[tx_rd_ptr_q];
        tx_rd_ptr_q <= tx_rd_ptr_q + 2'd1;
      end

      // ---- FIFO counts / memory ----
      if (apb_tx_push) begin
        tx_fifo[tx_wr_ptr_q] <= pwdata_i;
        tx_wr_ptr_q <= tx_wr_ptr_q + 2'd1;
      end
      if (eng_rx_push && !rx_full) begin
        rx_fifo[rx_wr_ptr_q] <= eng_rx_data;
        rx_wr_ptr_q <= rx_wr_ptr_q + 2'd1;
      end

      case ({apb_tx_push, eng_tx_pop})
        2'b10:   tx_cnt_q <= tx_cnt_q + 3'd1;
        2'b01:   tx_cnt_q <= tx_cnt_q - 3'd1;
        default: ;
      endcase
      case ({eng_rx_push && !rx_full, apb_rx_pop})
        2'b10:   rx_cnt_q <= rx_cnt_q + 3'd1;
        2'b01:   rx_cnt_q <= rx_cnt_q - 3'd1;
        default: ;
      endcase

      // ---- TX_DONE: transmitter drained and idle ----
      if (en_q && tx_en_q && tx_empty && (bit_cnt_q == 5'd0))
        tx_done_q <= 1'b1;
    end
  end

  assign sck_o = sck_q;
  assign ws_o  = ws_q;
  assign sd_o  = sd_o_q;

  assign irq_o    = (tx_done_q && tx_irq_en_q) || (rx_avail_q && rx_irq_en_q);
  assign tx_req_o = ~tx_full;
  assign rx_req_o = ~rx_empty;

  // -------------------------------------------------------------------------
  // APB read path
  // -------------------------------------------------------------------------
  reg [31:0] rx_pop_data_c;
  always @(*) begin
    rx_pop_data_c = rx_fifo[rx_rd_ptr_q];
  end

  always @(*) begin
    prdata_o = 32'h0;
    if (psel_i && penable_i && !pwrite_i) begin
      case (paddr_i[7:2])
        6'h00:   prdata_o = {26'h0, rx_irq_en_q, tx_irq_en_q, loop_q,
                             rx_en_q, tx_en_q, en_q};
        6'h01:   prdata_o = {16'h0, div_q};
        6'h03:   prdata_o = rx_pop_data_c;
        6'h04:   prdata_o = {27'h0, rx_full, rx_empty, tx_full, tx_empty, en_q};
        6'h05:   prdata_o = {30'h0, rx_avail_q, tx_done_q};
        default: prdata_o = 32'h0;
      endcase
    end
  end

  assign pready_o  = 1'b1;
  assign pslverr_o = 1'b0;

endmodule
